export const getMarketplaceStats = async (
  options?: RequestInit,
): Promise<MarketplaceStats> => {
  return customFetch<MarketplaceStats>(getGetMarketplaceStatsUrl(), {
    ...options,
    method: "GET",
  });
};

export const getGetMarketplaceStatsQueryKey = () => {
  return [`/api/stats/marketplace`] as const;
};

export const getGetMarketplaceStatsQueryOptions = <
  TData = Awaited<ReturnType<typeof getMarketplaceStats>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: UseQueryOptions<
    Awaited<ReturnType<typeof getMarketplaceStats>>,
    TError,
    TData
  >;
  request?: SecondParameter<typeof customFetch>;
}) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetMarketplaceStatsQueryKey();

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getMarketplaceStats>>
  > = ({ signal }) => getMarketplaceStats({ signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getMarketplaceStats>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetMarketplaceStatsQueryResult = NonNullable<
  Awaited<ReturnType<typeof getMarketplaceStats>>
>;
export type GetMarketplaceStatsQueryError = ErrorType<unknown>;

/**
 * @summary Get marketplace stats (service counts by category)
 */

export function useGetMarketplaceStats<
  TData = Awaited<ReturnType<typeof getMarketplaceStats>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: UseQueryOptions<
    Awaited<ReturnType<typeof getMarketplaceStats>>,
    TError,
    TData
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetMarketplaceStatsQueryOptions(options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
